// Seeded quorum commit simulation: verify strict linearizability across partitions
export function runSeededPartitionTest(seed: number, ops = 25000): boolean {
  const cluster = createCluster({ nodes: 5, seed, dropRate: 0.08 });
  for (let seq = 1; seq <= ops; seq++) {
    if (seq % 1400 === 0) cluster.healPartition();
    else if (seq % 900 === 0) cluster.isolateLeader();
    const res = cluster.propose({ key: `k-${seq % 64}`, val: seq });
    if (res.committed && res.term < cluster.minCommittedTerm()) return false;
  }
  return cluster.verifyAllReplicasConverged();
}
